INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Sicherheitsprotokolle nur für Webseiten wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für SSH, VPNs und mehr"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Sicherheitsprotokollen?', 3, '[{"text": "Sichere Datenübertragung", "correct": true, "because": "Schützt Kommunikation"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind typische Sicherheitsprotokolle?', 5, '[{"text": "HTTPS", "correct": true, "because": "Sichert Webverkehr"}, {"text": "SSH", "correct": true, "because": "Sichert Remote-Zugriff"}, {"text": "HTTP", "correct": false, "because": "Unsicher"}, {"text": "FTP", "correct": false, "because": "Keine Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) HTTPS nutzt TLS. b) SSH ist nur für lokale Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSH auch für Remote"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Sicherheitsprotokollen?', 4, '[{"text": "Verschlüsselung", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Authentifizierung", "correct": false, "because": "Bestätigt Identität"}, {"text": "Farbschema", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob HTTPS auch Integrität schützt?', 2, '[{"text": "Ja", "correct": true, "because": "TLS sichert Integrität"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll sichert Remote-Zugriff?', 3, '[{"text": "SSH", "correct": true, "because": "Verschlüsselter Zugriff"}, {"text": "Telnet", "correct": false, "because": "Unsicher"}, {"text": "HTTP", "correct": false, "because": "Kein Remote-Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle schützen Datenübertragung?', 5, '[{"text": "IPSec", "correct": true, "because": "Sichert Netzwerkebene"}, {"text": "SSL/TLS", "correct": true, "because": "Sichert Anwendungsebene"}, {"text": "FTP", "correct": false, "because": "Unsicher"}, {"text": "SMTP", "correct": false, "because": "Keine Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) HTTPS schützt vor Abhören. b) SSH ist nur für Server. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSH auch für Clients"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Sicherheitsprotokolle?', 4, '[{"text": "Zertifikate", "correct": false, "because": "Für HTTPS/TLS nötig"}, {"text": "Schlüsselpaare", "correct": false, "because": "Für SSH erforderlich"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist HTTPS dasselbe wie SSL?', 2, '[{"text": "Nein", "correct": true, "because": "HTTPS nutzt TLS, Nachfolger von SSL"}, {"text": "Ja", "correct": false, "because": "Technische Unterschiede"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle bieten Authentizierung?', 4, '[{"text": "SSH", "correct": true, "because": "Schlüsselbasierte Authentifizierung"}, {"text": "HTTPS", "correct": true, "because": "Zertifikate bestätigen Identität"}, {"text": "Telnet", "correct": false, "because": "Keine Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Sicherheitsprotokolle immer langsam sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Moderne Protokolle effizient"}, {"text": "Ja", "correct": false, "because": "Leistung optimierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Sicherheitsprotokollen?', 3, '[{"text": "Verschlüsselungsstärke", "correct": true, "because": "Sichert Daten"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SSH schützt Remote-Zugriff. b) HTTPS ist nur für Browser.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "HTTPS auch für APIs"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sichern Netzwerke?', 5, '[{"text": "IPSec", "correct": true, "because": "Verschlüsselt Netzwerkverkehr"}, {"text": "TLS", "correct": true, "because": "Sichert Anwendungen"}, {"text": "HTTP", "correct": false, "because": "Unsicher"}, {"text": "SMTP", "correct": false, "because": "Keine Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Sicherheitsprotokollen unwichtig?', 3, '[{"text": "Verschlüsselung", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Authentizität", "correct": false, "because": "Bestätigt Identität"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt SSH auch vor Datenmanipulation?', 3, '[{"text": "Ja", "correct": true, "because": "Integrität durch Verschlüsselung"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob HTTPS Zertifikate benötigt?', 2, '[{"text": "Ja", "correct": true, "because": "TLS-Zertifikate nötig"}, {"text": "Nein", "correct": false, "because": "Vertrauensbasis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für sichere Webseiten?', 4, '[{"text": "HTTPS", "correct": true, "because": "Standard für Web-Sicherheit"}, {"text": "FTP", "correct": false, "because": "Unsicher"}, {"text": "Telnet", "correct": false, "because": "Keine Verschlüsselung"}]');
